sys_script.script:
(function executeRule(current, previous /*null when async*/) {

(function executeRule(current, previous) {

    // Prevent Check Out before Check In
    if (current.u_status == 'checked_out') {

        // On insert, a visit cannot directly be Checked Out
        if (current.isNewRecord()) {
            gs.addErrorMessage(
                'A visit must be Checked In before it can be Checked Out.'
            );
            current.setAbortAction(true);
            return;
        }

        // On update, previous status must be Checked In
        if (previous.u_status != 'checked_in' &&
            previous.u_status != 'checked_out') {

            gs.addErrorMessage(
                'A visit must be Checked In before it can be Checked Out.'
            );
            current.setAbortAction(true);
            return;
        }

        // Check In time must exist
        if (!current.u_check_in) {
            gs.addErrorMessage(
                'Check In time is required before Check Out.'
            );
            current.setAbortAction(true);
            return;
        }

        // Set Check Out time if empty
        if (!current.u_check_out) {
            current.u_check_out = gs.nowDateTime();
        }
    }


    // Automatically set Check In time
    if (current.u_status == 'checked_in' &&
        !current.u_check_in) {

        current.u_check_in = gs.nowDateTime();
    }

})(current, previous);

})(current, previous);
